using BARANG.Core.Domain.Customers;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace BARANG.Core.Infrastructure.Persistence.Configurations;

internal static class CustomerConfiguration
{
    internal static void Base<T>(EntityTypeBuilder<T>b,string table)where T:class {b.ToTable(table,t=>t.HasCheckConstraint($"ck_{table}_version_positive","version > 0"));b.Property<Guid>("Id").HasColumnName("id").ValueGeneratedNever();b.Property<Guid>("CompanyId").HasColumnName("company_id");b.Property<DateTimeOffset>("CreatedAtUtc").HasColumnName("created_at_utc");b.Property<DateTimeOffset>("UpdatedAtUtc").HasColumnName("updated_at_utc");b.Property<long>("Version").HasColumnName("version").IsConcurrencyToken();}
}
internal sealed class CustomerEntityConfiguration:IEntityTypeConfiguration<Customer>
{
    public void Configure(EntityTypeBuilder<Customer>b){CustomerConfiguration.Base(b,"customers");b.HasKey(x=>x.Id).HasName("pk_customers");b.HasAlternateKey(x=>new{x.Id,x.CompanyId}).HasName("ak_customers_id_company_id");b.Property(x=>x.CustomerCode).HasColumnName("customer_code").HasMaxLength(50);b.Property(x=>x.CustomerType).HasColumnName("customer_type").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.DisplayName).HasColumnName("display_name").HasMaxLength(200);b.Property(x=>x.FirstName).HasColumnName("first_name").HasMaxLength(100);b.Property(x=>x.LastName).HasColumnName("last_name").HasMaxLength(100);b.Property(x=>x.LegalName).HasColumnName("legal_name").HasMaxLength(200);b.Property(x=>x.NationalId).HasColumnName("national_id").HasMaxLength(64);b.Property(x=>x.RegistrationNo).HasColumnName("registration_no").HasMaxLength(64);b.Property(x=>x.TaxId).HasColumnName("tax_id").HasMaxLength(64);b.Property(x=>x.PrimaryMobile).HasColumnName("primary_mobile").HasMaxLength(16);b.Property(x=>x.PrimaryPhone).HasColumnName("primary_phone").HasMaxLength(16);b.Property(x=>x.PrimaryEmail).HasColumnName("primary_email").HasMaxLength(320);b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(2000);b.Property(x=>x.IsActive).HasColumnName("is_active");b.HasOne<Domain.Organization.Company>().WithMany().HasForeignKey(x=>x.CompanyId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_customers_companies_company_id");b.HasIndex(x=>new{x.CompanyId,x.CustomerCode}).IsUnique().HasDatabaseName("uq_customers_company_code");b.HasIndex(x=>new{x.CompanyId,x.NationalId}).HasFilter("national_id IS NOT NULL").IsUnique().HasDatabaseName("uq_customers_company_national_id");b.HasIndex(x=>new{x.CompanyId,x.RegistrationNo}).HasFilter("registration_no IS NOT NULL").IsUnique().HasDatabaseName("uq_customers_company_registration_no");b.HasIndex(x=>new{x.CompanyId,x.IsActive,x.CustomerCode}).HasDatabaseName("ix_customers_directory");b.HasIndex(x=>new{x.CompanyId,x.DisplayName}).HasDatabaseName("ix_customers_company_display_name");b.HasIndex(x=>new{x.CompanyId,x.PrimaryMobile}).HasDatabaseName("ix_customers_company_mobile");b.HasIndex(x=>new{x.CompanyId,x.PrimaryEmail}).HasDatabaseName("ix_customers_company_email");}
}
internal sealed class CustomerContactConfiguration:IEntityTypeConfiguration<CustomerContact>
{
    public void Configure(EntityTypeBuilder<CustomerContact>b){CustomerConfiguration.Base(b,"customer_contacts");b.HasKey(x=>x.Id).HasName("pk_customer_contacts");b.Property(x=>x.CustomerId).HasColumnName("customer_id");b.Property(x=>x.ContactTypeCode).HasColumnName("contact_type_code").HasMaxLength(50);b.Property(x=>x.Name).HasColumnName("name").HasMaxLength(200);b.Property(x=>x.Mobile).HasColumnName("mobile").HasMaxLength(16);b.Property(x=>x.Phone).HasColumnName("phone").HasMaxLength(16);b.Property(x=>x.Email).HasColumnName("email").HasMaxLength(320);b.Property(x=>x.JobTitle).HasColumnName("job_title").HasMaxLength(150);b.Property(x=>x.IsPrimary).HasColumnName("is_primary");b.Property(x=>x.IsActive).HasColumnName("is_active");b.Property(x=>x.DisplayOrder).HasColumnName("display_order");b.HasOne<Customer>().WithMany().HasForeignKey(x=>new{x.CustomerId,x.CompanyId}).HasPrincipalKey(x=>new{x.Id,x.CompanyId}).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_customer_contacts_customers_customer_company");b.HasIndex(x=>new{x.CompanyId,x.CustomerId,x.DisplayOrder,x.Id}).HasDatabaseName("ix_customer_contacts_customer_order");b.HasIndex(x=>new{x.CustomerId,x.IsPrimary}).HasFilter("is_primary AND is_active").IsUnique().HasDatabaseName("uq_customer_contacts_one_active_primary");}
}
internal sealed class CustomerAddressConfiguration:IEntityTypeConfiguration<CustomerAddress>
{
    public void Configure(EntityTypeBuilder<CustomerAddress>b){CustomerConfiguration.Base(b,"customer_addresses");b.HasKey(x=>x.Id).HasName("pk_customer_addresses");b.Property(x=>x.CustomerId).HasColumnName("customer_id");b.Property(x=>x.AddressTypeCode).HasColumnName("address_type_code").HasMaxLength(50);b.Property(x=>x.Title).HasColumnName("title").HasMaxLength(100);b.Property(x=>x.CountryCode).HasColumnName("country_code").HasMaxLength(2);b.Property(x=>x.Province).HasColumnName("province").HasMaxLength(150);b.Property(x=>x.City).HasColumnName("city").HasMaxLength(150);b.Property(x=>x.District).HasColumnName("district").HasMaxLength(150);b.Property(x=>x.AddressLine1).HasColumnName("address_line1").HasMaxLength(500);b.Property(x=>x.AddressLine2).HasColumnName("address_line2").HasMaxLength(500);b.Property(x=>x.PostalCode).HasColumnName("postal_code").HasMaxLength(32);b.Property(x=>x.RecipientName).HasColumnName("recipient_name").HasMaxLength(200);b.Property(x=>x.RecipientPhone).HasColumnName("recipient_phone").HasMaxLength(16);b.Property(x=>x.IsPrimary).HasColumnName("is_primary");b.Property(x=>x.IsActive).HasColumnName("is_active");b.Property(x=>x.DisplayOrder).HasColumnName("display_order");b.HasOne<Customer>().WithMany().HasForeignKey(x=>new{x.CustomerId,x.CompanyId}).HasPrincipalKey(x=>new{x.Id,x.CompanyId}).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_customer_addresses_customers_customer_company");b.HasIndex(x=>new{x.CompanyId,x.CustomerId,x.DisplayOrder,x.Id}).HasDatabaseName("ix_customer_addresses_customer_order");b.HasIndex(x=>new{x.CustomerId,x.IsPrimary}).HasFilter("is_primary AND is_active").IsUnique().HasDatabaseName("uq_customer_addresses_one_active_primary");}
}
